ND */)\r\n\r\n  MEASURE 'Consolidation'[First Load] = \r\n    (/* USER DAX BEGIN */\r\nCALCULATE(FIRSTNONBLANK ('Load Port'[Load Port Code], TRUE () ), TOPN(1,'Consolidation Transport','Consolidation Transport'[Leg Order],ASC))\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Consolidation'[Last Discharge] = \r\n    (/* USER DAX BEGIN */\r\n\r\n            CALCULATE (\r\n                FIRSTNONBLANK ( 'Consolidation Transport'[Discharge Port Code], TRUE () ),\r\n                TOPN (\r\n                    1,\r\n                    'Consolidation Transport',\r\n                    'Consolidation Transport'[Leg Order], DESC\r\n                )\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Consolidation'[Console ATA] = \r\n    (/* USER DAX BEGIN */\r\n\r\n            VAR code =\r\n                FIRSTNONBLANK ( 'Company Branch'[Country Code], TRUE () )\r\n            RETURN\r\n                CALCULATE (\r\n                    FIRSTNONBLANK ( 'Main Transport'[ATA], TRUE () ),\r\n                    FILTER ( 'Main Transport', 'Main Transport'[Country Code] = code )\r\n                )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Consolidation'[Console ATD] = \r\n    (/* USER DAX BEGIN */\r\n\r\nVAR code =\r\n        FIRSTNONBLANK ( 'Company Branch'[Country Code], TRUE () )\r\nRETURN\r\n                CALCULATE (\r\n                    FIRSTNONBLANK ( 'Main Transport'[ATD], TRUE () ),\r\n                    FILTER ( 'Main Transport', 'Main Transport'[Country Code] = code )\r\n                )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Entry Number'[Contract No] = \r\n    (/* USER DAX BEGIN */\r\n\r\nCONCATENATEX(\r\n        CALCULATETABLE (\r\n            'Entry Number',\r\n            'Entry Number'[Parent Table] = \"JobConsol\",\r\n            'Entry Number'[Category] = \"OTH\",\r\n            'Entry Number'[Entry Type] = \"CON\"\r\n        ),'Entry Number'[Entry Num])\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[20F] = \r\n    (/* USER DAX BEGIN */\r\nSUM