r 40R] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[40H] = \r\n    (/* USER DAX BEGIN */\r\nSUMX (\r\n                GROUPBY (\r\n                    FILTER ( 'Pack Line', 'Pack Line'[__Included For Container Count] = TRUE ),\r\n                    'Pack Line'[Container Key],\r\n                    \"Count\", MAXX ( CURRENTGROUP (), 'Pack Line'[Container 40H] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[45F] = \r\n    (/* USER DAX BEGIN */\r\nSUMX (\r\n                GROUPBY (\r\n                    FILTER ( 'Pack Line', 'Pack Line'[__Included For Container Count] = TRUE ),\r\n                    'Pack Line'[Container Key],\r\n                    \"Count\", MAXX ( CURRENTGROUP (), 'Pack Line'[Container 45F] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[GEN] = \r\n    (/* USER DAX BEGIN */\r\nSUMX (\r\n                GROUPBY (\r\n                    FILTER ( 'Pack Line', 'Pack Line'[__Included For Container Count] = TRUE ),\r\n                    'Pack Line'[Container Key],\r\n                    \"Count\", MAXX ( CURRENTGROUP (), 'Pack Line'[Container GEN] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[Other] = \r\n    (/* USER DAX BEGIN */\r\nSUMX (\r\n                GROUPBY (\r\n                    FILTER ( 'Pack Line', 'Pack Line'[__Included For Container Count] = TRUE ),\r\n                    'Pack Line'[Container Key],\r\n                    \"Count\", MAXX ( CURRENTGROUP (), 'Pack Line'[Container Other] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Container'[Container_Count] = \r\n    (/* USER DAX BEGIN */\r\n\r\nSUMX (\r\n                GROUPBY (\r\n                    FILTER ( 'Pack Line', 'Pack Line'[__Included For Container Count] = TRUE ),\r\n                    'Pack Line'[Container Key],\r\n                    \"Count\", MAXX ( CURRENTGROUP (), 'Pack Line'[Container Count] )\r\n                ),\r\n                [Count]\r\n            )\r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Shipment'[Customs Info] = \r\n    (/* USER DAX BEGIN */\r\nCONCATENATEX(DISTINCT('Shipment Customs Info'), 'Shipment Customs Info'[Entry Type]& \" \" & 'Shipment Customs Info'[Entry Number]  ,\",\") \r\n/* USER DAX END */)\r\n\r\n  MEASURE 'Shipment'[Freight Direction] = \r\n    (/* USER DAX BEGIN */\r\n\r\n\r\nvar selectedDirection = FIRSTNONBLANK('Parameter Values - Freight Direction'[Freight Direction Code],TRUE())\r\n\r\nvar direction = \r\n IF(FIRSTNONBLANK('Port Of Destination'[Port Of Destination Country Code], TRUE()) = FIRSTNONBLANK('Company Branch'[Country Code], TRUE()) && FIRSTNONBLANK('Port Of Origin'[Port Of Origin Country Code], TRUE()) <> FIRSTNONBLANK('Company Branch'[Country Code], TRUE()), \"Import\", IF(FIRSTNONBLANK('Port Of Destination'[Port Of Destination Country Code], TRUE()) <> FIRSTNONBLANK('Company Branch'[Country Code], TRUE()) && FIRSTNONBLANK('Port Of Origin'[Port Of Origin Country Code], TRUE()) = FIRSTNONBLANK('Company Branch'[Country Code], TRUE()), \"Export\", \"Other/Cross Trade\"))\r\n\r\nreturn IF ( COUNTROWS(Shipment)> 0, IF(selectedDirection = LEFT(direction,3) || selectedDirection = \"ALL\", direction))\r\n\r\n\r\n/* USER DAX END */)\r\n\r\n  VAR __DS0FilterTable = \r\n    FILTER(\r\n      KEEPFILTERS(VALUES('Parameter Values - Freight Direction'[Freight Direction Name])),\r\n      'Parameter Values - Freight Direction'[Freight Direction Name] = \"All Shipments\"\r\n    )\r\n\r\n  VAR __DS0FilterTable2 = \r\n    FILTER(\r\n      KEEPFILTERS(VALUES('Parameter Values - CoLoad Type'[CoLoad Type Name])),\r\n      'Parameter Values - CoLoad Type'[CoLoad Type Name] = \"All Shipments\"\r\n    )\r\n\r\n  VAR __DS0FilterTable3 = \r\n    FILTER(\r\